import { useEffect, useState } from "react";
import { Table, Spinner, Alert, Button } from "react-bootstrap";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch("http://localhost:8000/api/comandes");

      if (!response.ok) {
        throw new Error("Error al obtenir les comandes");
      }

      const data = await response.json();

      // ✅ Igual que productes: la API devuelve un array
      setOrders(data);
    } catch (err) {
      console.error(err);
      setError("Error al obtenir les comandes");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  if (orders.length === 0) {
    return <p className="mt-3">No hi ha comandes disponibles</p>;
  }

  return (
    <div className="mt-4">
      <h2>Llista de Comandes</h2>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Client</th>
            <th>Total</th>
            <th>Estat</th>
            <th>Data</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((comanda) => (
            <tr key={comanda.id}>
              <td>{comanda.id}</td>
              <td>{comanda.nom_client ?? "—"}</td>
              <td>{comanda.total} €</td>
              <td>{comanda.estat}</td>
              <td>
                {new Date(comanda.created_at).toLocaleDateString("ca-ES")}
              </td>
              <td>
                <Button variant="warning" size="sm" className="me-2">
                  Editar
                </Button>
                <Button variant="danger" size="sm">
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </div>
  );
}

export default OrdersList;
